def main():

    values = []



    # Continuously prompt the user for values until "stop" is entered

    while True:

        user_input = input("Enter a value or stop to end: ")

        if user_input.lower() == "stop":

            break

        try:

            value = float(user_input)

            values.append(value)

        except ValueError:

            print("Invalid input. Please enter a numerical value or 'stop'.")



    # Ask the user for the threshold value

    threshold = float(input("Enter a threshold value: "))



    # Calculate and print the average of values greater than the threshold

    filtered_values = [val for val in values if val > threshold]

    if filtered_values:

        average = sum(filtered_values) / len(filtered_values)

        print(f"The average of the values greater than {threshold} is {round(average, 2)}")

    else:

        print("No values greater than the threshold were entered.")



if __name__ == "__main__":

    main()

