def is_valid_password(password):

    number=0

    alpha=0

    digit=0

    while number<len(password):

        if password[number].isalpha():

            alpha+=1

        elif password[number].isdigit():

            digit+=1

        number+=1

    if len(password)<10 or '123'in password or 'abc'in password or alpha<5 or digit<4:

        return False

    else:

        return True

