def classify_em_wave(wavelength):

    if wavelength < 1e-11:

        return "Gamma"

    elif wavelength >= 1e-11 and wavelength < 1e-8:

        return "X-Ray"

    elif wavelength >= 1e-8 and wavelength < 3.8e-7:

        return "Ultraviolet"

    elif wavelength >= 3.8e-7 and wavelength < 7.5e-7:

        return "Visible"

    elif wavelength >= 7.5e-7 and wavelength < 1e-3:

        return "Infrared"

    elif wavelength >= 1e-3 and wavelength < 1:

        return "Microwave"

    elif wavelength >= 1:

        return "Radio"



