    if n == 0:

        return 0

    elif n == 1:

        return 1

    else:

        pell_minus_2 = 0

        pell_minus_1 = 1

        for _ in range(2, n + 1):

            pell = 2 * pell_minus_1 + pell_minus_2

            pell_minus_2 = pell_minus_1

            pell_minus_1 = pell

        return pell

